window.docContents[119].resolve({"/rules/RG1007/#RG1007-limitations":{"contents":"Term-parameterized and partial-application registrations are unsupported shapes, not proofs of incorrectness; restate them as closed full-domain contracts.\n\n","context":"Regula rule reference\u0009Rule index\u0009RG1007: Executable contracts require supported closed evidence","header":"Limitations and unsupported cases","id":"/rules/RG1007/#RG1007-limitations"},"/rules/RG4004/#RG4004-limitations":{"contents":"Teaching fences are re-elaborated for authentication, so their imports are paid twice; keep them small.\n\n","context":"Regula rule reference\u0009Rule index\u0009RG4004: Teaching examples require authenticated compiler classification","header":"Limitations and unsupported cases","id":"/rules/RG4004/#RG4004-limitations"},"/rules/RG5003/#RG5003-limitations":{"contents":"Setext headings and closing sequences such as # Intent # are not recognized as Intent headings.\n\nThe editor reports this rule only when the module has finished elaborating without errors; a module with elaboration errors gets RG2005 (incomplete) instead.\n\n","context":"Regula rule reference\u0009Rule index\u0009RG5003: Registered public material declarations require an Intent section","header":"Limitations and unsupported cases","id":"/rules/RG5003/#RG5003-limitations"}});